/// Номера значков; порядок совпадает с `GLYPHS`.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Icon {
    Dot,
    OilField,
    GasField,
    Drop,
    Flame,
    Refinery,
    Plant,
    Tank,
    Thermal,
    Coal,
    Hydro,
    Nuclear,
    Port,
    Airport,
    Pick,
}

pub const ALL: [Icon; 15] = [
    Icon::Dot,
    Icon::OilField,
    Icon::GasField,
    Icon::Drop,
    Icon::Flame,
    Icon::Refinery,
    Icon::Plant,
    Icon::Tank,
    Icon::Thermal,
    Icon::Coal,
    Icon::Hydro,
    Icon::Nuclear,
    Icon::Port,
    Icon::Airport,
    Icon::Pick,
];

impl Icon {
    pub fn key(self) -> &'static str {
        match self {
            Icon::Dot => "dot",
            Icon::OilField => "oil",
            Icon::GasField => "gas",
            Icon::Drop => "drop",
            Icon::Flame => "flame",
            Icon::Refinery => "factory",
            Icon::Plant => "plant",
            Icon::Tank => "tank",
            Icon::Thermal => "bolt",
            Icon::Coal => "coal",
            Icon::Hydro => "wave",
            Icon::Nuclear => "atom",
            Icon::Port => "port",
            Icon::Airport => "plane",
            Icon::Pick => "pick",
        }
    }

    pub fn title(self) -> &'static str {
        match self {
            Icon::Dot => "Точка",
            Icon::OilField => "Нефтедобыча",
            Icon::GasField => "Газодобыча",
            Icon::Drop => "Капля",
            Icon::Flame => "Огонь",
            Icon::Refinery => "НПЗ",
            Icon::Plant => "Завод",
            Icon::Tank => "Терминал / хранилище",
            Icon::Thermal => "Электростанция",
            Icon::Coal => "Уголь",
            Icon::Hydro => "Вода",
            Icon::Nuclear => "Атом",
            Icon::Port => "Порт",
            Icon::Airport => "Аэропорт",
            Icon::Pick => "Добыча",
        }
    }

    pub fn from_key(key: &str) -> Option<Icon> {
        ALL.iter().copied().find(|i| i.key() == key)
    }

    /// Треугольники значка в единичном квадрате (по три точки, y вниз).
    pub fn tris(self) -> &'static [[f32; 2]] {
        GLYPHS[self as usize]
    }
}

